import { z } from 'zod';
import { ASK_MAX_HISTORY, ASK_MAX_QUESTION } from './limits';

/**
 * Input schemas for every Server Action. Every client value is parsed here before a service sees it.
 */

/** Time the worker performed the action, from the offline outbox. Must be ISO 8601 with a zone. */
const capturedAt = z.iso.datetime({ offset: true }).optional();
/** Idempotency key generated by the client (a random UUID). */
const clientId = z
  .string()
  .regex(/^[A-Za-z0-9-]{8,64}$/, 'Invalid client id')
  .optional();
const recordId = z.string().regex(/^[A-Za-z0-9_-]{1,80}$/, 'Invalid id');

// ── Auth Schemas ────────────────────────────────────────────
export const workerLoginSchema = z.object({
  phone: z.string().regex(/^\d{10}$/, 'Phone must be 10 digits'),
  pin: z.string().regex(/^\d{4}$/, 'PIN must be 4 digits'),
});

export const adminLoginSchema = z.object({
  email: z.email('Invalid email').max(254),
  password: z.string().min(6, 'Password must be at least 6 characters').max(128),
});

// ── Check-in Schemas ────────────────────────────────────────
export const checkinQrSchema = z.object({
  siteId: recordId,
  code: z.string().regex(/^\d{6}$/, 'Code must be 6 digits'),
  capturedAt,
  clientId,
});

export const checkinGpsSchema = z.object({
  siteId: recordId,
  lat: z.number().min(-90).max(90),
  lng: z.number().min(-180).max(180),
  capturedAt,
  clientId,
});

export const checkoutSchema = z.object({
  shiftId: recordId.optional(),
  capturedAt,
  clientId,
});

// ── Hazard Schemas ──────────────────────────────────────────
export const hazardReportSchema = z.object({
  siteId: recordId,
  category: z.string().trim().min(1).max(80),
  description: z.string().trim().min(1, 'Describe the hazard').max(2000),
  severity: z.enum(['critical', 'high', 'medium', 'low']),
  anonymous: z.boolean().default(false),
  capturedAt,
  clientId,
});

// ── Feedback Schema ─────────────────────────────────────────
export const feedbackSchema = z.object({
  siteId: recordId,
  managerRespect: z.number().int().min(1).max(5),
  safetyRating: z.number().int().min(1).max(5),
  payFairness: z.number().int().min(1).max(5),
  workloadRating: z.number().int().min(1).max(5),
  comment: z.string().trim().max(2000).nullable().default(null),
  capturedAt,
  clientId,
});

// ── Admin Schemas ───────────────────────────────────────────
export const hazardIdSchema = recordId;
export const hazardSeveritySchema = z.enum(['critical', 'high', 'medium', 'low']);

// ── Assistant Schema ────────────────────────────────────────

/** A question plus the last few turns, kept on the client only and re-sent for context. */
export const askSchema = z.object({
  question: z.string().trim().min(1).max(ASK_MAX_QUESTION),
  history: z
    .array(
      z.object({
        role: z.enum(['user', 'assistant']),
        text: z.string().max(1500),
      }),
    )
    .max(ASK_MAX_HISTORY)
    .default([]),
});
